+const menuToggle = document.querySelector(".menu-toggle");
+const navLinks = document.querySelector(".nav-links");
+const filterButtons = document.querySelectorAll(".filter-button");
+const productCards = document.querySelectorAll(".product-card");
+const cartButtons = document.querySelectorAll(".add-to-cart");
+const cartCount = document.querySelector("#cart-count");
+const signupForm = document.querySelector("#signup-form");
+const formMessage = document.querySelector("#form-message");
+
+let cartItems = 0;
+
+menuToggle.addEventListener("click", () => {
+  const isOpen = menuToggle.getAttribute("aria-expanded") === "true";
+  menuToggle.setAttribute("aria-expanded", String(!isOpen));
+  navLinks.classList.toggle("open", !isOpen);
+  document.body.classList.toggle("menu-open", !isOpen);
+});
+
+navLinks.addEventListener("click", (event) => {
+  if (event.target.matches("a")) {
+    menuToggle.setAttribute("aria-expanded", "false");
+    navLinks.classList.remove("open");
+    document.body.classList.remove("menu-open");
+  }
+});
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const selectedCategory = button.dataset.filter;
+
+    filterButtons.forEach((currentButton) => {
+      const isActive = currentButton === button;
+      currentButton.classList.toggle("active", isActive);
+      currentButton.setAttribute("aria-pressed", String(isActive));
+    });
+
+    productCards.forEach((card) => {
+      const shouldShow = selectedCategory === "all" || card.dataset.category === selectedCategory;
+      card.classList.toggle("hidden", !shouldShow);
+    });
+  });
+});
+
+cartButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    cartItems += 1;
+    cartCount.textContent = String(cartItems);
+    button.textContent = "Added";
+
+    window.setTimeout(() => {
+      button.textContent = "Add to cart";
+    }, 1200);
+  });
+});
+
+const updateCountdown = () => {
+  const now = new Date();
+  const dealEnds = new Date(now);
+  dealEnds.setDate(now.getDate() + ((5 - now.getDay() + 7) % 7 || 7));
+  dealEnds.setHours(23, 59, 59, 999);
+
+  const distance = dealEnds - now;
+  const days = Math.floor(distance / (1000 * 60 * 60 * 24));
+  const hours = Math.floor((distance / (1000 * 60 * 60)) % 24);
+  const minutes = Math.floor((distance / (1000 * 60)) % 60);
+
+  document.querySelector("#days").textContent = String(days).padStart(2, "0");
+  document.querySelector("#hours").textContent = String(hours).padStart(2, "0");
+  document.querySelector("#minutes").textContent = String(minutes).padStart(2, "0");
+};
+
+signupForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const email = new FormData(signupForm).get("email");
+  formMessage.textContent = `Thanks. Early access details will be sent to ${email}.`;
+  signupForm.reset();
+});
+
+updateCountdown();
+window.setInterval(updateCountdown, 60000);
